args:
query=query WayfinderMaps($owner: String!, $repo: String!) {
  repository(owner: $owner, name: $repo) {
    m5: issue(number: 5) { ...WayfinderMap }
    m6: issue(number: 6) { ...WayfinderMap }
  }
  rateLimit { remaining resetAt }
}

fragment WayfinderMap on Issue {
  number
  title
  url
  body
  subIssues(first: 100) {
    nodes {
      number
      title
      url
      state
      body
      labels(first: 50) { nodes { name } }
      assignees(first: 10) { nodes { login } }
      parent { number }
      blockedBy(first: 50) { nodes { number title state url } }
      comments(last: 1) { nodes { author { login } createdAt body } }
    }
  }
}
